00178     private function setValue($key, $subkey, $entry, $value, $type)
00179     {
00180         global $bearsamppLang;
00181 
00182         $this->latestError = null;
00183 
00184         $this->writeLog('SetValue ' . $key . '\\' . $subkey . '\\' . $entry);
00185         $this->writeLog('-> value: ' . $value);
00186         $this->writeLog('-> type: ' . $type);
00187 
00188         // Map the VBS type to Win32Native registry type
00189         $regType = self::REG_SZ; // Default
00190         if ($type == 'SetExpandedStringValue') {
00191             $regType = self::REG_EXPAND_SZ;
00192         } elseif ($type == 'SetStringValue') {
00193             $regType = self::REG_SZ;
00194         }
00195 
00196         // Handle delete operations
00197         if ($type == 'DeleteValue' && !empty($entry)) {
00198             // Delete a value
00199             $result = Win32Native::registryDeleteValue($key, $subkey, $entry);
00200         } elseif ($type == 'DeleteValue' && empty($entry)) {
00201             // Delete a key
00202             $result = Win32Native::registryDeleteKey($key, $subkey);
00203         } else {
00204             // Set a value
00205             $result = Win32Native::registrySetValue($key, $subkey, $entry, $value, $regType);
00206         }
00207 
00208         if ($subkey == self::ENV_KEY) {
00209             Batch::refreshEnvVars();
00210         }
00211 
00212         $this->writeLog('-> result: ' . ($result ? 'success' : 'failed'));
00213 
00214         if (!$result) {
00215             $this->latestError = $bearsamppLang->getValue(Lang::ERROR) . ' Registry operation failed';
00216             return false;
00217         }
00218 
00219         // Verify the value was set correctly (for set operations)
00220         if ($type != 'DeleteValue' && !empty($value)) {
00221             $verifyValue = Win32Native::registryGetValue($key, $subkey, $entry);
00222             if ($verifyValue != $value) {
00223                 $this->latestError = sprintf($bearsamppLang->getValue(Lang::REGISTRY_SET_ERROR_TEXT), $value);
00224                 return false;
00225             }
00226         }
00227 
00228         return true;
00229     }
